@Injectable()
export class PubSubProvider implements OnModuleDestroy {
  private initializePubSub(): void {
    const nodeEnv = String(...).toLowerCase();

    // In-memory for dev/test
    if (nodeEnv === "development" || nodeEnv === "test" || nodeEnv === "e2e") {
      this.pubSub = new PubSub();
      this.isRedisBacked = false;
      return;
    }

    // Redis for production - separate publisher/subscriber connections
    this.publisher = new Redis(redisUrl, {...});
    this.subscriber = new Redis(redisUrl, {...});
    this.pubSub = new RedisPubSub({
      publisher: this.publisher,
      subscriber: this.subscriber,
    });
  }
}
